children:
:root { color-scheme: light; --crays-red: #ff1f57; --crays-ink: #04101d; --crays-muted: #5f6b7a; --crays-line: #e5eaf0; --crays-soft: #f5f7fa; }
body { margin: 0; font-family: Montserrat, Arial, sans-serif; color: var(--crays-ink); background: #fff; }
.crays-wiki-shell { width: min(1180px, calc(100% - 36px)); margin: 0 auto; }
.crays-wiki-header { border-bottom: 1px solid var(--crays-line); background: #fff; }
.crays-wiki-header__inner { min-height: 86px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
.crays-wiki-logo img { display: block; width: 132px; height: auto; }
.crays-wiki-nav { display: flex; flex-wrap: wrap; gap: 18px; font-weight: 800; font-size: 0.85rem; }
.crays-wiki-nav a { color: var(--crays-ink); text-decoration: none; }
.crays-wiki-hero { background: #04101d; color: #fff; padding: 84px 0 72px; }
.crays-wiki-kicker { margin: 0 0 12px; color: var(--crays-red); font-size: 0.78rem; font-weight: 900; text-transform: uppercase; letter-spacing: 0.04em; }
.crays-wiki-hero h1 { max-width: 820px; margin: 0; font-size: clamp(2.4rem, 7vw, 5.6rem); line-height: 0.95; letter-spacing: 0; }
.crays-wiki-hero p:not(.crays-wiki-kicker) { max-width: 760px; margin: 22px 0 0; color: rgba(255,255,255,0.82); font-size: 1.08rem; line-height: 1.75; font-weight: 700; }
.crays-wiki-stats { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 28px; }
.crays-wiki-stats span { border: 1px solid rgba(255,255,255,0.22); border-radius: 999px; padding: 9px 14px; font-size: 0.82rem; font-weight: 900; color: #fff; }
.crays-wiki-intro { padding: 34px 0 18px; }
.crays-wiki-section-nav { display: flex; flex-wrap: wrap; gap: 8px; }
.crays-wiki-section-nav a { color: var(--crays-ink); text-decoration: none; border: 1px solid var(--crays-line); border-radius: 999px; padding: 8px 12px; font-size: 0.78rem; font-weight: 900; background: #fff; }
.crays-nostr-wiki-group { padding: 34px 0; border-top: 1px solid var(--crays-line); }
.crays-nostr-wiki-group header { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 14px; align-items: end; margin-bottom: 18px; }
.crays-nostr-wiki-group header p { grid-column: 1 / -1; margin: 0 0 -6px; color: var(--crays-red); font-size: 0.74rem; font-weight: 900; text-transform: uppercase; }
.crays-nostr-wiki-group h2 { margin: 0; font-size: clamp(1.6rem, 4vw, 3rem); line-height: 1; letter-spacing: 0; }
.crays-nostr-wiki-group header span { color: var(--crays-muted); font-weight: 900; }
.crays-nostr-wiki-group ol { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 10px; }
.crays-nostr-wiki-group li { min-width: 0; }
.crays-nostr-wiki-group li a { min-height: 132px; display: grid; gap: 8px; align-content: start; padding: 16px; border: 1px solid var(--crays-line); border-radius: 8px; color: var(--crays-ink); text-decoration: none; background: #fff; }
.crays-nostr-wiki-group li a:hover { border-color: var(--crays-red); }
.crays-nostr-wiki-group strong { font-size: 0.98rem; line-height: 1.25; }
.crays-nostr-wiki-group span { color: var(--crays-muted); font-size: 0.82rem; line-height: 1.45; font-weight: 600; }
.crays-nostr-wiki-group small { color: #8a94a3; font-size: 0.72rem; line-height: 1.4; overflow-wrap: anywhere; }
.crays-wiki-footer { border-top: 1px solid var(--crays-line); padding: 32px 0; color: var(--crays-muted); font-size: 0.82rem; font-weight: 700; }
@media (max-width: 720px) {
  .crays-wiki-header__inner { align-items: flex-start; flex-direction: column; padding: 18px 0; }
  .crays-wiki-nav { gap: 12px; }
  .crays-wiki-hero { padding: 58px 0 52px; }
  .crays-nostr-wiki-group header { grid-template-columns: 1fr; }
}
